import{_ as r,o as t,c as a,a2 as o}from"./chunks/framework.DqYch1Cg.js";const c=JSON.parse('{"title":"浏览器机制串联自测","description":"","frontmatter":{},"headers":[],"relativePath":"学习自测/12broswer/q_bw_4-browser_review.md","filePath":"学习自测/12broswer/q_bw_4-browser_review.md","lastUpdated":1794211306000}'),s={name:"学习自测/12broswer/q_bw_4-browser_review.md"};function n(i,e,p,l,_,h){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="浏览器机制串联自测" tabindex="-1">浏览器机制串联自测 <a class="header-anchor" href="#浏览器机制串联自测" aria-label="Permalink to &quot;浏览器机制串联自测&quot;">​</a></h1><h2 id="_1-事件循环和渲染如何配合" tabindex="-1">1. 事件循环和渲染如何配合？ <a class="header-anchor" href="#_1-事件循环和渲染如何配合" aria-label="Permalink to &quot;1. 事件循环和渲染如何配合？&quot;">​</a></h2><p><strong>参考回答：</strong> 主线程执行当前任务后会在规定时机进行微任务检查，浏览器在合适的渲染机会更新页面。Promise 回调和 queueMicrotask 常进入微任务；不断加入微任务可能延迟后续任务和渲染，不是“异步就不卡”。浏览器不会保证每轮都渲染，也不固定每16毫秒刷新一次。</p><p><strong>验证：</strong> 比较 setTimeout 与 Promise 的日志顺序，再用长微任务链观察页面响应。不要把后台标签页节流当正常前台时序。</p><h2 id="_2-捕获、目标与冒泡的顺序" tabindex="-1">2. 捕获、目标与冒泡的顺序？ <a class="header-anchor" href="#_2-捕获、目标与冒泡的顺序" aria-label="Permalink to &quot;2. 捕获、目标与冒泡的顺序？&quot;">​</a></h2><p><strong>参考回答：</strong> 事件沿路径进行捕获，到达目标，再在支持冒泡的事件中向外传播。目标上的捕获和非捕获监听器也有各自阶段规则，不能一概说“同节点只按注册顺序”。stopPropagation 不等于阻止默认行为，preventDefault 也不停止传播；passive 监听器不能靠 preventDefault 阻止默认行为。</p><p><strong>验证：</strong> 在父子元素分别注册捕获与冒泡监听，记录 eventPhase、target、currentTarget；事件委托还需考虑事件是否冒泡、Shadow DOM 重定向和组件销毁清理。</p><h2 id="_3-从-html-到屏幕发生了什么" tabindex="-1">3. 从 HTML 到屏幕发生了什么？ <a class="header-anchor" href="#_3-从-html-到屏幕发生了什么" aria-label="Permalink to &quot;3. 从 HTML 到屏幕发生了什么？&quot;">​</a></h2><p><strong>参考回答：</strong> 解析 HTML / CSS，建立相关结构，计算样式和布局，再绘制与合成。脚本、样式和资源优先级会影响进程，不是所有步骤严格一次性串行。DOMContentLoaded 与解析及相关延迟脚本有关；load 也不代表所有懒加载资源都完成。</p><p><strong>追问：</strong> transform 动画一定不重绘吗？读取 offsetWidth 为什么有时触发布局、有时不会？关联<a href="/FE-prepare-interview/概念与原理/06opt/s_opt_11-loading_rendering">资源与渲染</a>。</p><h2 id="_4-浏览器存储怎样选" tabindex="-1">4. 浏览器存储怎样选？ <a class="header-anchor" href="#_4-浏览器存储怎样选" aria-label="Permalink to &quot;4. 浏览器存储怎样选？&quot;">​</a></h2><p><strong>参考回答：</strong> 少量偏好可放 localStorage，大量结构化数据适合 IndexedDB；Cookie 用于随请求携带的状态，sessionStorage 面向页面会话。都要考虑作用域、同步成本、配额与回收。IndexedDB 不是无限空间，也不是无需同步的服务端替代品。</p><p><strong>追问：</strong> 两个标签页的 sessionStorage 是否总相同？删除浏览器缓存会清掉哪些存储？应区分工具操作选项而非统一下结论。</p><h2 id="_5-跨域问题如何定位" tabindex="-1">5. 跨域问题如何定位？ <a class="header-anchor" href="#_5-跨域问题如何定位" aria-label="Permalink to &quot;5. 跨域问题如何定位？&quot;">​</a></h2><p><strong>参考回答：</strong> 先比较协议、主机、端口，再看是否预检、请求是否实际发出、返回哪些 CORS 字段、凭据模式是否匹配。CORS 限制浏览器脚本读取，不是服务器拒绝一切跨源流量。开发代理让浏览器请求同源地址，实际服务端仍要设计生产跨域策略。</p><p><strong>追问：</strong> 为什么简单表单可造成跨站写操作？iframe 跨源通信应使用校验 origin 与数据结构的 postMessage，而不是放开整个同源策略。</p><p>关联：<a href="/FE-prepare-interview/概念与原理/04http/s_http_8-cors_identity">CORS 与身份机制</a>、<a href="/FE-prepare-interview/概念与原理/06opt/s_opt_12-storage_cache">浏览器存储</a>。</p><blockquote><p>来源：<a href="https://github.com/Fridolph/Fridolph/tree/c3a1eda8e0f7fe08d8ec54e07d07db514cbfc5d7/interviewMap/Browser" target="_blank" rel="noreferrer">个人 interviewMap / Browser</a>；<a href="https://developer.mozilla.org/zh-CN/docs/Web/API/Document_Object_Model/Events" target="_blank" rel="noreferrer">MDN DOM 事件</a>；<a href="https://html.spec.whatwg.org/multipage/webappapis.html#event-loops" target="_blank" rel="noreferrer">HTML 事件循环规范</a>。</p></blockquote>',18)])])}const g=r(s,[["render",n]]);export{c as __pageData,g as default};
